-- ============================================================================
-- [ZxR-GUEST] Guest Login bridge — hooks into GuestLogin_BGMI.lua
-- Active only when GuestLogin_BGMI.lua already loaded; silent no-op otherwise.
-- ============================================================================
local function _ZxR_GuestIsLoaded()
    return rawget(_G, "__ZxR_GUEST_SCRIPT_LOADED") == true
end

local function _ZxR_GuestLog(msg)
    local logger = rawget(_G, "ZxRLog")
    if type(logger) == "function" then
        pcall(logger, "[BRGuestBridge] " .. tostring(msg))
    else
        pcall(print, "[ZxR][BRGuestBridge] " .. tostring(msg))
    end
end

local function _ZxR_InstallGuestHooksSafe()
    if not _ZxR_GuestIsLoaded() then return false end
    local installer = rawget(_G, "ZxR_TryInstallGuestLoginHooks")
    if type(installer) ~= "function" then return false end
    local ok = pcall(installer)
    return ok
end
