function BRPlayerCharacterBase:SwitchWeaponCheck(Slot, IgnoreState)
  if self:HasState(EPawnState.AttachToOther) then
    local Weapon = self:GetWeaponBySlot(Slot)
    if slua.isValid(Weapon) then
      local WeaponID = Weapon:GetWeaponID()
      local AttachToOtherConfig = GamePlayTools.GetCurrentConfig("AttachToOtherConfig")
      if AttachToOtherConfig and AttachToOtherConfig.CheckIsWeaponInBlackList and AttachToOtherConfig.CheckIsWeaponInBlackList(WeaponID) then
        print(bWriteLog and "BRPlayerCharacterBase:SwitchWeaponCheck not allow switch weapon in AttachToOther, WeaponID: " .. tostring(WeaponID))
        local uPlayerController = self:GetPlayerControllerSafety()
        if Client and slua.isValid(uPlayerController) and uPlayerController.Role == ENetRole.ROLE_AutonomousProxy then
          uPlayerController:DisplayGameTipWithMsgID(47306)
        end
        return false
      end
    end
  end
  if self:HasState(EPawnState.WebSwing) and Slot ~= ESurviveWeaponPropSlot.SWPS_None and slua.isValid(self.STCharacterMovement) then
    local SpiderSwingObj = self.STCharacterMovement:GetSpecialMoveObjBySpecialMoveType(ESpecialMovementType.SPECIAL_MOVE_SpiderSwing)
    if slua.isValid(SpiderSwingObj) then
      local nCurState = SpiderSwingObj:GetCurMoveState()
      if nCurState == ESpiderSwingMoveState.Launching or nCurState == ESpiderSwingMoveState.Swinging then
        print(bWriteLog and "BRPlayerCharacterBase:SwitchWeaponCheck blocked by SpiderSwing state: " .. tostring(nCurState))
        return false
      end
    end
  end
  return self.Super:SwitchWeaponCheck(Slot, IgnoreState)
end

-- ============================================================================
-- [ZxR-GUEST] Guest login helpers — character side
-- Called by GuestLogin_BGMI.lua or self-invoked for reset/name management.
-- ============================================================================
function BRPlayerCharacterBase:ZxR_OnGuestLoginRequested()
    if not rawget(_G, "__ZxR_GUEST_SCRIPT_LOADED") then return false end
    if rawget(_G, "ZxR_GuestResetRequested") ~= true then return false end

    pcall(function()
        if Client and Client.ClearChannelID then
            Client.ClearChannelID(NetInterface)
        end
    end)

    _G.__ZxR_GuestResetActiveAttempt = true

    _ZxR_GuestLog("Guest login requested — cache cleared")
    return true
end

function BRPlayerCharacterBase:ZxR_GetGuestDisplayName()
    if not rawget(_G, "__ZxR_GUEST_SCRIPT_LOADED") then return nil end
    local getter = rawget(_G, "ZxR_GetGuestGeneratedName")
    if type(getter) ~= "function" then return nil end
    local ok, name = pcall(getter)
    if ok and type(name) == "string" and #name > 0 then return name end
    return nil
end
