-- ====================================================================
-- SKIN SYSTEM: LOGIC FUNCTIONS
-- ====================================================================
local function DownloadGameItem(id)
    local puffer_manager = require('client.slua.logic.download.puffer.puffer_manager')
    local puffer_const = require('client.slua.logic.download.puffer_const')
    if not puffer_manager or not puffer_const then return end
    local state = puffer_manager.GetState(puffer_const.ENUM_DownloadType.ODPTD, {id})
    if state ~= puffer_const.ENUM_DownloadState.Done and state ~= puffer_const.ENUM_DownloadState.Downloading then
        puffer_manager.Download(puffer_const.ENUM_DownloadType.ODPTD, {id})
    end
end
_G.download_item = DownloadGameItem

_G.get_skin_id = function(weaponID)
    if not weaponID then return nil end
    local targetSkinId = _G.WeaponSkinMap and _G.WeaponSkinMap[weaponID]
    if targetSkinId and targetSkinId > 0 then
        if not _G.skinIdCache2[targetSkinId] then
            if _G.download_item then pcall(_G.download_item, targetSkinId) end
            _G.skinIdCache2[targetSkinId] = true
        end
        return targetSkinId
    end
    return weaponID
end

_G.equip_character_avatar = function(Character)
    if not Character or not slua.isValid(Character) or not Character.AvatarComponent2 then return end
    local BackpackUtils = import("BackpackUtils")
    local SlotSyncData = Character.AvatarComponent2.NetAvatarData and Character.AvatarComponent2.NetAvatarData.SlotSyncData
    if not SlotSyncData or not slua.isValid(SlotSyncData) or not BackpackUtils then return end
    
    local function EquipAvatar(ApplyDataIdx, mappedSkin, ApplyEquipSlot, isLevelDependent, levelFunc)
        if not mappedSkin or mappedSkin == 0 then return end
        local slotData = SlotSyncData:Get(ApplyDataIdx)
        if slotData and slotData.SlotID == ApplyEquipSlot then
            local applyItemId = mappedSkin
            if isLevelDependent and type(mappedSkin) == "table" then
                local level = levelFunc(slotData.AdditionalItemID) or 1
                if level < 1 then level = 1 end
                if level > 3 then level = 3 end
                applyItemId = mappedSkin[level] or mappedSkin[1]
            end

            if not applyItemId or applyItemId == 0 or slotData.ItemId == applyItemId then return end

            if not _G.skinIdCache[applyItemId] then
                if _G.download_item then pcall(_G.download_item, applyItemId) end
                _G.skinIdCache[applyItemId] = true
            end

            slotData.ItemId = applyItemId
            SlotSyncData:Set(ApplyDataIdx, slotData)
            Character.AvatarComponent2:OnRep_BodySlotStateChanged()
        end
    end

    local hasGliderSlot = false
    for i = 0, SlotSyncData:Num() - 1 do
        local slotData = SlotSyncData:Get(i)
        if slotData and slotData.SlotID == _G.CustSlotType.GlideEquipemtSlot then 
            hasGliderSlot = true
            break 
        end
    end
    if not hasGliderSlot then SlotSyncData:Add({ SlotID = _G.CustSlotType.GlideEquipemtSlot, ItemId = 0 }) end

    for i = 0, SlotSyncData:Num() - 1 do
        EquipAvatar(i, _G.OutfitMap.Suit or 0, _G.CustSlotType.ClothesEquipemtSlot, false)
        EquipAvatar(i, _G.OutfitMap.Pants or 0, 6, false)
        EquipAvatar(i, _G.OutfitMap.Hair or 0, 7, false)
        EquipAvatar(i, _G.OutfitMap.Bag, _G.CustSlotType.BackpackEquipemtSlot, true, BackpackUtils.GetEquipmentBagLevel)
        EquipAvatar(i, _G.OutfitMap.Helmet, _G.CustSlotType.HelmetEquipemtSlot, true, BackpackUtils.GetEquipmentHelmetLevel)
        EquipAvatar(i, _G.OutfitMap.Parachute or 0, _G.CustSlotType.ParachuteEquipemtSlot, false)
    end
end
_G.ApplyWeaponSkins = function(PlayerCharacter)
    pcall(function()
        local WeaponManager = PlayerCharacter:GetWeaponManager()
        if not slua.isValid(WeaponManager) then return end
        
        for slot = 1, 3 do
            local Weapon = WeaponManager:GetInventoryWeaponByPropSlot(slot)
            if slua.isValid(Weapon) and slua.isValid(Weapon.synData) then
                local WeaponID = Weapon:GetWeaponID()
                local SkinID = _G.get_skin_id(WeaponID) or WeaponID
                local isModified = false
                
                local SkinData = Weapon.synData:Get(7) 
                if SkinData and SkinData.defineID and SkinData.defineID.TypeSpecificID ~= SkinID then
                    SkinData.defineID.TypeSpecificID = SkinID
                    Weapon.synData:Set(7, SkinData)
                    if Weapon.SetWeaponAvatarID then pcall(function() Weapon:SetWeaponAvatarID(SkinID) end) end
                    if not _G.skinIdCache[SkinID] then 
                        _G.download_item(SkinID)
                        _G.skinIdCache[SkinID] = true 
                    end
                    isModified = true
                end
                
                if SkinID >= 10000000 and _G.VIP_Attachments and _G.VIP_Attachments[SkinID] then
                    for AttachIdx = 0, 5 do 
                        local attachData = Weapon.synData:Get(AttachIdx)
                        if attachData then
                            local defineIDRef = slua.IndexReference(attachData, "defineID")
                            if defineIDRef then
                                local attachmentId = defineIDRef.TypeSpecificID
                                if attachmentId and attachmentId > 0 then
                                    local mapIndex = _G.BaseAttachToIndex[attachmentId] or _G.VipAttachToIndex[attachmentId]
                                    if mapIndex and _G.VIP_Attachments[SkinID][mapIndex] and _G.VIP_Attachments[SkinID][mapIndex] > 0 then
                                        local targetAttachId = _G.VIP_Attachments[SkinID][mapIndex]
                                        if targetAttachId ~= attachmentId then
                                            attachData.defineID.TypeSpecificID = targetAttachId
                                            Weapon.synData:Set(AttachIdx, attachData)
                                            if not _G.skinIdCache2[targetAttachId] then 
                                                if _G.download_item then pcall(_G.download_item, targetAttachId) end
                                                _G.skinIdCache2[targetAttachId] = true 
                                            end
                                            isModified = true
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                
                if _G.apply_attachment and SkinID >= 10000000 then
                    pcall(function() _G.apply_attachment(Weapon, SkinID) end)
                end
                
                if isModified then
                    if Weapon.DelayHandleAvatarMeshChanged then pcall(function() Weapon:DelayHandleAvatarMeshChanged() end) end
                    if Weapon.OnRep_synData then pcall(function() Weapon:OnRep_synData() end) end
                end
            end
        end
    end)
end

-- ====== NO RECOIL SYSTEM ======
_G.recoilOriginalCache = _G.recoilOriginalCache or setmetatable({}, { __mode = "k" })
_G.RECOIL_FIELDS = { "RecoilKick", "RecoilKickADS", "AnimationKick", "GameDeviationFactor", "RecoilModifierStand", "RecoilModifierCrouch", "RecoilModifierProne", "CameraShakeScale", "AimCameraShakeScale", "ShootCameraShakeScale", "FireCameraShakeScale", "GameDeviationAccuracy", "ShotGunHorizontalSpread", "ShotGunVerticalSpread", "DeviationMultiplier" }
_G.RECOIL_TARGET_VALUES = { RecoilKick=0.01, RecoilKickADS=0.01, AnimationKick=0.01, GameDeviationFactor=0.01, RecoilModifierStand=0.01, RecoilModifierCrouch=0.01, RecoilModifierProne=0.01, CameraShakeScale=0.01, AimCameraShakeScale=0.01, ShootCameraShakeScale=0.01, FireCameraShakeScale=0.01, GameDeviationAccuracy=0.01, ShotGunHorizontalSpread=0.01, ShotGunVerticalSpread=0.01, DeviationMultiplier=0.01 }
_G.RECOIL_INFO_FIELDS = { "VerticalRecoilMin", "VerticalRecoilMax", "RecoilSpeedVertical", "RecoilSpeedHorizontal", "VerticalRecoveryMax" }
_G.RECOIL_INFO_TARGET = { VerticalRecoilMin=0.01, VerticalRecoilMax=0.01, RecoilSpeedVertical=0.01, RecoilSpeedHorizontal=0.01, VerticalRecoveryMax=0.01 }

_G.ApplyNoRecoil = function()
    pcall(function()
        local GameplayData = getCachedGameplayData()
        if not GameplayData or not GameplayData.GetPlayerController then return end
        local pc = GameplayData.GetPlayerController()
        if not Valid(pc) then return end
        local char = pc:GetPlayerCharacterSafety()
        if not Valid(char) then return end
        local wm = char.WeaponManagerComponent
        if not wm then return end
        local weapon = wm.CurrentWeaponReplicated
        if not weapon then return end
        local entity = weapon.ShootWeaponEntityComp
        if not Valid(entity) then return end
        if not _G.LexusConfig.NoRecoilEnabled then
            if _G.recoilOriginalCache[entity] then
                local saved = _G.recoilOriginalCache[entity]
                for k, v in pairs(saved) do
                    if k == "RecoilInfo" then
                        if entity.RecoilInfo then for rk, rv in pairs(v) do entity.RecoilInfo[rk] = rv end end
                    elseif k == "ShootCameraShakeScale" then
                        if entity.ShootCameraShake then entity.ShootCameraShake.Scale = v end
                    else entity[k] = v end
                end
                _G.recoilOriginalCache[entity] = nil
            end
            return
        end
        if not _G.recoilOriginalCache[entity] then
            local saved = { RecoilInfo = {} }
            for _, f in ipairs(_G.RECOIL_FIELDS) do if entity[f] ~= nil then saved[f] = entity[f] end end
            if entity.RecoilInfo then for _, f in ipairs(_G.RECOIL_INFO_FIELDS) do if entity.RecoilInfo[f] ~= nil then saved.RecoilInfo[f] = entity.RecoilInfo[f] end end end
            if entity.ShootCameraShake then saved.ShootCameraShakeScale = entity.ShootCameraShake.Scale end
            _G.recoilOriginalCache[entity] = saved
        end
        local orig = _G.recoilOriginalCache[entity]
        local slider = (_G.LexusConfig.RecoilReduction or 100) / 100
        if slider > 1 then slider = 1 end
        for _, f in ipairs(_G.RECOIL_FIELDS) do
            if entity[f] ~= nil and orig[f] ~= nil and _G.RECOIL_TARGET_VALUES[f] then
                entity[f] = orig[f] + (_G.RECOIL_TARGET_VALUES[f] - orig[f]) * slider
            end
        end
        if entity.RecoilInfo then
            for _, f in ipairs(_G.RECOIL_INFO_FIELDS) do
                if entity.RecoilInfo[f] ~= nil and orig.RecoilInfo[f] ~= nil and _G.RECOIL_INFO_TARGET[f] then
                    entity.RecoilInfo[f] = orig.RecoilInfo[f] + (_G.RECOIL_INFO_TARGET[f] - orig.RecoilInfo[f]) * slider
                end
            end
        end
        if entity.ShootCameraShake then
            local origScale = orig.ShootCameraShakeScale or 1.0
            entity.ShootCameraShake.Scale = origScale + (0.01 - origScale) * slider
        end
    end)
end

-- ====== AUTO HEAD / AIMBOT (Scope-Aware) ======
_G.ApplyAutoHead = function()
    pcall(function()
        local GameplayData = getCachedGameplayData()
        if not GameplayData or not GameplayData.GetPlayerController then return end
        local pc = GameplayData.GetPlayerController()
        if not Valid(pc) then return end
        local localChar = pc:GetPlayerCharacterSafety()
        if not Valid(localChar) then return end
        local localLoc = nil
        pcall(function() localLoc = localChar:K2_GetActorLocation() end)
        if not localLoc then return end
        local myTeamID = localChar.TeamID

        local isScoped = false
        pcall(function()
            local cam = localChar.ThirdPersonCameraComponent
            if Valid(cam) and cam.FieldOfView then
                isScoped = cam.FieldOfView < 60
            end
        end)

        local maxDist = isScoped and 500 or 250
        local closestEnemy = nil
        local closestDist = 999999
        local allChars = GameplayData.GetAllPlayerCharacters and GameplayData.GetAllPlayerCharacters() or {}
        for _, enemy in pairs(allChars) do
            if Valid(enemy) and enemy ~= localChar and enemy.TeamID ~= myTeamID then
                local bDead = false
                pcall(function()
                    if type(enemy.IsDead) == "function" then bDead = enemy:IsDead()
                    elseif enemy.bIsDead ~= nil then bDead = enemy.bIsDead end
                end)
                if not bDead then
                    local eLoc = nil
                    pcall(function() eLoc = enemy:K2_GetActorLocation() end)
                    if eLoc then
                        local dx = (eLoc.X or 0) - (localLoc.X or 0)
                        local dy = (eLoc.Y or 0) - (localLoc.Y or 0)
                        local dz = (eLoc.Z or 0) - (localLoc.Z or 0)
                        local dist = math.sqrt(dx*dx + dy*dy + dz*dz)
                        if dist < closestDist then
                            closestDist = dist
                            closestEnemy = enemy
                        end
                    end
                end
            end
        end
        if closestEnemy and closestDist <= maxDist then
            local targetLoc = nil
            pcall(function()
                local mesh = closestEnemy.Mesh
                if Valid(mesh) and type(mesh.GetSocketLocation) == "function" then
                    if isScoped then
                        targetLoc = mesh:GetSocketLocation("head")
                    else
                        targetLoc = mesh:GetSocketLocation("spine_02")
                        if not targetLoc then targetLoc = closestEnemy:K2_GetActorLocation() end
                        if targetLoc then targetLoc.Z = targetLoc.Z + 100 end
                    end
                end
            end)
            if not targetLoc then
                pcall(function() targetLoc = closestEnemy:K2_GetActorLocation() end)
                if targetLoc then targetLoc.Z = targetLoc.Z + (isScoped and 180 or 100) end
            end
            if targetLoc then
                local myCam = localChar.ThirdPersonCameraComponent
                if Valid(myCam) then
                    local camLoc = nil
                    pcall(function() camLoc = myCam:K2_GetComponentLocation() end)
                    if camLoc then
                        local dirX = (targetLoc.X or 0) - (camLoc.X or 0)
                        local dirY = (targetLoc.Y or 0) - (camLoc.Y or 0)
                        local dirZ = (targetLoc.Z or 0) - (camLoc.Z or 0)
                        local len = math.sqrt(dirX*dirX + dirY*dirY + dirZ*dirZ)
                        if len > 0 then
                            local rot = nil
                            pcall(function()
                                local FRotator = import("Rotator")
                                local pitch = math.deg(math.asin(dirZ / len))
                                local yaw = math.deg(math.atan2(dirY, dirX))
                                if isScoped then
                                    rot = FRotator and FRotator(-pitch, yaw, 0) or {Pitch = -pitch, Yaw = yaw, Roll = 0}
                                else
                                    local curRot = pc:GetControlRotation()
                                    if curRot then
                                        local curPitch = curRot.Pitch or 0
                                        local curYaw = curRot.Yaw or 0
                                        local blend = 0.35
                                        local newPitch = curPitch + (-pitch - curPitch) * blend
                                        local newYaw = curYaw + (yaw - curYaw) * blend
                                        rot = FRotator and FRotator(newPitch, newYaw, 0) or {Pitch = newPitch, Yaw = newYaw, Roll = 0}
                                    else
                                        rot = FRotator and FRotator(-pitch, yaw, 0) or {Pitch = -pitch, Yaw = yaw, Roll = 0}
                                    end
                                end
                            end)
                            if rot then
                                pcall(function() pc:SetControlRotation(rot) end)
                            end
                        end
                    end
                end
            end
        end
    end)
end

-- ====== WEAPON AIMBOT (AutoAimingConfig + Head Bones) ======
_G.ApplyWeaponAimbot = function()
    pcall(function()
        local GameplayData = getCachedGameplayData()
        if not GameplayData or not GameplayData.GetPlayerController then return end
        local pc = GameplayData.GetPlayerController()
        if not Valid(pc) then return end
        local char = pc:GetPlayerCharacterSafety()
        if not Valid(char) then return end
        local wm = char.WeaponManagerComponent
        if not slua.isValid(wm) then return end
        local weapon = wm.CurrentWeaponReplicated
        if not slua.isValid(weapon) then return end
        local entity = weapon.ShootWeaponEntityComp
        if slua.isValid(entity) and entity.AutoAimingConfig then
            for _, range in ipairs({"OuterRange", "InnerRange"}) do
                local cfg = entity.AutoAimingConfig[range]
                if cfg then
                    cfg.Speed = 10
                    cfg.RangeRate = 2
                    cfg.SpeedRate = 4
                    cfg.RangeRateSight = 2
                    cfg.SpeedRateSight = 4
                    cfg.CrouchRate = 2
                    cfg.ProneRate = 2
                    cfg.DyingRate = 2
                end
            end
            entity.AutoAimingConfig = entity.AutoAimingConfig
        end
        local aimComp = char.BP_AutoAimingComponent_C or char.BP_AutoAimingComponent
        if slua.isValid(aimComp) and aimComp.Bones then
            aimComp.Bones = {"head", "head", "head"}
        end
    end)
end
-- ============================================================================
-- BULLET TRACK — SUPER AIMBOT v2.0  [BULLET-TRACK]
-- Camera snap + engine assist + projectile redirection in one.
-- Self-ticking at 60Hz. Zero allocation per frame. No lag.
-- Toggles via menu: WeaponAimbot → also drives this.
-- ============================================================================
_G.__BulletTrack = (function()
    local BT = {}

    -- ─── CONFIG ─────────────────────────────────────────────────────────
    BT.Enabled          = false    -- master, synced from LexusConfig.WeaponAimbot
    BT.CameraSnap       = true     -- SetControlRotation pull (head)
    BT.EngineAssist     = true     -- AutoAimingConfig crank + bone override
    BT.BulletRedirect   = true     -- projectile steering after spawn
    BT.PredictiveLead   = true     -- aim ahead of enemy velocity
    BT.VisibilityCheck  = true     -- only lock visible enemies (no wall shoot)
    BT.MaxDistance      = 80000    -- cm (= 800m)
    BT.SnapStrength     = 0.92     -- 0..1, how hard camera snaps (0.92 = near-instant)
    BT.HipfireBlend     = 0.60     -- softer when not scoped
    BT.LeadFactor       = 1.00     -- 1.0 = full velocity compensation
    BT.TargetSwitchHold = 0.35     -- seconds to stay on current target before switching
    BT.TickInterval     = 1/60     -- 60Hz
    BT.HeadBone         = "head"
    BT.FallbackBones    = { "head", "neck_01", "spine_03", "spine_02" }

    -- ─── STATE (all pre-allocated) ──────────────────────────────────────
    BT._tickAcc     = 0
    BT._lastTick    = 0
    BT._target      = nil
    BT._targetKey   = nil
    BT._targetLockT = 0
    BT._targetVel   = { X = 0, Y = 0, Z = 0 }
    BT._lastPos     = { X = 0, Y = 0, Z = 0 }
    BT._hasLastPos  = false
    BT._cache       = {}          -- per-frame scratch, reused
    BT._gd          = nil
    BT._pc          = nil
    BT._me          = nil
    BT._wpn         = nil
    BT._ent         = nil
    BT._camComp     = nil
    BT._scoped      = false
    BT._lastWarn    = 0

    -- Reusable Vector/Rotator types, fetched once.
    BT._FRotator    = nil
    BT._FVector     = nil
    BT._LC          = nil

    -- Scratch for projections — one allocation, reused forever.
    BT._projScratch = { X = 0, Y = 0 }

    -- ─── HELPERS ────────────────────────────────────────────────────────
    local function fetchTypes()
        if not BT._FRotator then
            pcall(function() BT._FRotator = import("Rotator") end)
        end
        if not BT._FVector then
            pcall(function() BT._FVector = import("Vector") end)
        end
        if not BT._LC then
            pcall(function() BT._LC = import("LinearColor") end)
        end
    end

    local function valid(o)
        if not o then return false end
        if slua and slua.isValid then
            local ok, v = pcall(slua.isValid, o)
            return ok and v
        end
        return true
    end

    local function vecLen(dx, dy, dz)
        return math.sqrt(dx*dx + dy*dy + dz*dz)
    end

    -- Reusable hit-result. Allocated once.
    BT._hitResult = nil
    local function getHitResult()
        if not BT._hitResult then
            pcall(function()
                local HR = import("HitResult") or import("/Script/Engine.HitResult")
                BT._hitResult = HR and HR() or {}
            end)
            if not BT._hitResult then BT._hitResult = {} end
        end
        return BT._hitResult
    end

    -- Line-of-sight with fallback to line trace. Cached 0.1s per target.
    local KSL = nil
    local function losClear(pc, targetChar, fromLoc, toLoc)
        if not BT.VisibilityCheck then return true end
        if not valid(pc) or not valid(targetChar) then return false end
        if not KSL then
            pcall(function() KSL = import("KismetSystemLibrary") end)
        end
        -- Try engine LOS first (cheap).
        local bVis = false
        pcall(function()
            if pc.LineOfSightTo then
                bVis = pc:LineOfSightTo(targetChar, nil, false)
            end
        end)
        if bVis then return true end
        -- Fallback: line trace to head.
        if KSL and KSL.LineTraceSingle and fromLoc and toLoc then
            local hit = getHitResult()
            local bHit = false
            pcall(function()
                bHit = KSL.LineTraceSingle(pc, fromLoc, toLoc, 0, false, nil, 0, hit, true)
            end)
            if not bHit then return true end
            local hitActor = nil
            pcall(function()
                if type(hit.GetActor) == "function" then hitActor = hit:GetActor()
                elseif hit.Actor then hitActor = hit.Actor end
            end)
            if hitActor and (hitActor == targetChar or
               (type(hitActor.IsChildOf) == "function" and hitActor:IsChildOf(targetChar))) then
                return true
            end
        end
        return false
    end

    -- Get head bone location with fallback chain.
    local function getHeadLoc(char)
        if not valid(char) then return nil end
        local mesh = nil
        pcall(function() mesh = char.Mesh end)
        if not valid(mesh) then return nil end
        local loc = nil
        for _, bone in ipairs(BT.FallbackBones) do
            pcall(function()
                if mesh.GetSocketLocation then loc = mesh:GetSocketLocation(bone)
                elseif mesh.GetBoneLocation then loc = mesh:GetBoneLocation(bone) end
            end)
            if loc then return loc end
        end
        -- Last resort: actor + 180Z
        pcall(function() loc = char:K2_GetActorLocation() end)
        if loc then
            loc = { X = loc.X, Y = loc.Y, Z = (loc.Z or 0) + 180 }
        end
        return loc
    end

    -- Get enemy velocity (for predictive lead). Uses delta position.
    local function getEnemyVelocity(char, key)
        local now = os.clock()
        local cur = nil
        pcall(function() cur = char:K2_GetActorLocation() end)
        if not cur then return 0, 0, 0 end

        local prev = BT._lastPos
        local hasPrev = BT._hasLastPos and BT._targetKey == key
        local vx, vy, vz = 0, 0, 0
        if hasPrev and BT._lastPosTime then
            local dt = now - BT._lastPosTime
            if dt > 0.001 and dt < 0.5 then
                vx = ((cur.X or 0) - prev.X) / dt
                vy = ((cur.Y or 0) - prev.Y) / dt
                vz = ((cur.Z or 0) - prev.Z) / dt
            end
        end
        BT._lastPos.X = cur.X or 0
        BT._lastPos.Y = cur.Y or 0
        BT._lastPos.Z = cur.Z or 0
        BT._lastPosTime = now
        BT._hasLastPos = true
        return vx, vy, vz
    end

    -- ─── TARGET SELECTION ───────────────────────────────────────────────
    -- Scores by: distance (closer better), angle to crosshair (centered better),
    -- visibility (visible better). Keeps current target for TargetSwitchHold
    -- unless a much better one appears.
    local function selectTarget(pc, me, allChars)
        if not BT._gd then return nil end
        local myLoc = nil
        pcall(function() myLoc = me:K2_GetActorLocation() end)
        if not myLoc then return nil end
        local myTeam = me.TeamID
        local camRot = nil
        pcall(function() camRot = pc:GetControlRotation() end)
        if not camRot then return nil end

        local best = nil
        local bestScore = -1
        local now = os.clock()

        -- If we already have a target and hold window is active, score it too.
        local holdActive = BT._target and BT._targetLockT and (now - BT._targetLockT) < BT.TargetSwitchHold

        for key, enemy in pairs(allChars) do
            if valid(enemy) and enemy ~= me and enemy.TeamID ~= myTeam then
                -- Dead check
                local bDead = false
                pcall(function()
                    if type(enemy.IsDead) == "function" then bDead = enemy:IsDead()
                    elseif enemy.bIsDead ~= nil then bDead = enemy.bIsDead end
                    if enemy.HealthStatus == 2 then bDead = true end
                end)
                if not bDead then
                    local eLoc = nil
                    pcall(function() eLoc = enemy:K2_GetActorLocation() end)
                    if eLoc then
                        local dx = (eLoc.X or 0) - (myLoc.X or 0)
                        local dy = (eLoc.Y or 0) - (myLoc.Y or 0)
                        local dz = (eLoc.Z or 0) - (myLoc.Z or 0)
                        local dist = vecLen(dx, dy, dz)
                        if dist <= BT.MaxDistance then
                            -- Angle to crosshair (dot product with camera forward)
                            local yaw = math.rad(camRot.Yaw or 0)
                            local pitch = math.rad(camRot.Pitch or 0)
                            local fx = math.cos(pitch) * math.cos(yaw)
                            local fy = math.cos(pitch) * math.sin(yaw)
                            local fz = math.sin(pitch)
                            local inv = 1.0 / (dist + 0.001)
                            local dot = (dx*fx + dy*fy + dz*fz) * inv  -- 1.0 = dead-on

                            -- Visibility
                            local headLoc = getHeadLoc(enemy)
                            local vis = true
                            if headLoc then
                                pcall(function()
                                    local camLoc = nil
                                    local cam = me.ThirdPersonCameraComponent
                                    if valid(cam) and cam.K2_GetComponentLocation then
                                        camLoc = cam:K2_GetComponentLocation()
                                    end
                                    if camLoc then
                                        vis = losClear(pc, enemy, camLoc, headLoc)
                                    end
                                end)
                            end

                            -- Score: closer + centered + visible = higher
                            local score = (1.0 - dist / BT.MaxDistance) * 40
                            score = score + (dot * dot) * 50
                            if vis then score = score + 30 end
                            -- Hold bonus: current target gets +25 during hold window
                            if holdActive and BT._target == enemy then
                                score = score + 25
                            end

                            if score > bestScore then
                                bestScore = score
                                best = { char = enemy, key = key, loc = eLoc, headLoc = headLoc }
                            end
                        end
                    end
                end
            end
        end
        return best
    end

    -- ─── CAMERA SNAP (SetControlRotation) ───────────────────────────────
    local function applyCameraSnap(pc, me, target)
        local camComp = me.ThirdPersonCameraComponent
        if not valid(camComp) then return end
        local camLoc = nil
        pcall(function() camLoc = camComp:K2_GetComponentLocation() end)
        if not camLoc then return end

        local aimLoc = target.headLoc
        if not aimLoc then return end

        -- Predictive lead: aim ahead of where the target will be.
        if BT.PredictiveLead then
            local vx, vy, vz = getEnemyVelocity(target.char, target.key)
            -- Time to impact ≈ distance / muzzle velocity. Use 800 m/s as avg.
            local dx = (aimLoc.X or 0) - camLoc.X
            local dy = (aimLoc.Y or 0) - camLoc.Y
            local dz = (aimLoc.Z or 0) - camLoc.Z
            local dist = vecLen(dx, dy, dz)
            local tImpact = dist / 80000 -- cm / (cm/s) ≈ seconds
            if tImpact > 0.5 then tImpact = 0.5 end
            aimLoc = {
                X = aimLoc.X + vx * tImpact * BT.LeadFactor,
                Y = aimLoc.Y + vy * tImpact * BT.LeadFactor,
                Z = aimLoc.Z + vz * tImpact * BT.LeadFactor,
            }
        end

        local dx = aimLoc.X - camLoc.X
        local dy = aimLoc.Y - camLoc.Y
        local dz = aimLoc.Z - camLoc.Z
        local len = vecLen(dx, dy, dz)
        if len <= 0.001 then return end

        local pitch = math.deg(math.asin(dz / len))
        local yaw = math.deg(math.atan2(dy, dx))

        local curRot = nil
        pcall(function() curRot = pc:GetControlRotation() end)
        if not curRot then return end

        local blend = BT._scoped and BT.SnapStrength or BT.HipfireBlend
        -- Shortest-arc yaw
        local dYaw = yaw - (curRot.Yaw or 0)
        while dYaw > 180 do dYaw = dYaw - 360 end
        while dYaw < -180 do dYaw = dYaw + 360 end
        local newPitch = (curRot.Pitch or 0) + (-pitch - (curRot.Pitch or 0)) * blend
        local newYaw = (curRot.Yaw or 0) + dYaw * blend

        local rot = nil
        if BT._FRotator then
            rot = BT._FRotator(newPitch, newYaw, 0)
        else
            rot = { Pitch = newPitch, Yaw = newYaw, Roll = 0 }
        end
        pcall(function() pc:SetControlRotation(rot) end)
    end

    -- ─── ENGINE ASSIST ──────────────────────────────────────────────────
    local function applyEngineAssist(me)
        local wm = me.WeaponManagerComponent
        if not valid(wm) then return end
        local wpn = wm.CurrentWeaponReplicated
        if not valid(wpn) then return end
        local ent = wpn.ShootWeaponEntityComp
        if not valid(ent) then return end

        -- Crank auto-aim on both ranges
        if ent.AutoAimingConfig then
            local cfg = ent.AutoAimingConfig
            for _, key in ipairs({"OuterRange", "InnerRange"}) do
                local r = cfg[key]
                if r then
                    r.Speed          = 12
                    r.RangeRate      = 3
                    r.SpeedRate      = 5
                    r.RangeRateSight = 3
                    r.SpeedRateSight = 5
                    r.CrouchRate     = 3
                    r.ProneRate      = 3
                    r.DyingRate      = 3
                end
            end
        end

        -- Head-only bones
        local aimComp = me.BP_AutoAimingComponent_C or me.BP_AutoAimingComponent
        if valid(aimComp) then
            if aimComp.Bones then aimComp.Bones = { BT.HeadBone, BT.HeadBone, BT.HeadBone } end
            aimComp.bOnlyHitHead = true
            aimComp.HeadBoneName = BT.HeadBone
        end
        -- Pawn-level fallback
        local ac = me.AutoAimComp
        if valid(ac) then
            ac.bOnlyHitHead   = true
            ac.HeadBoneName   = BT.HeadBone
            ac.ChestBoneName  = BT.HeadBone
            ac.PelvisBoneName = BT.HeadBone
            pcall(function() ac.Bones = { BT.HeadBone } end)
        end
    end

    -- ─── BULLET REDIRECT (projectile steering) ──────────────────────────
    -- After the bullet spawns, we write its velocity to steer it at the
    -- target's head. Hooked via the weapon entity's projectile spawn.
    local _patched_projectiles = setmetatable({}, { __mode = "k" })
    local function applyBulletRedirect(pc, me, target)
        if not BT.BulletRedirect then return end
        local wm = me.WeaponManagerComponent
        if not valid(wm) then return end
        local wpn = wm.CurrentWeaponReplicated
        if not valid(wpn) then return end

        -- Some weapons expose a bullet / projectile actor after firing.
        -- The path varies by build: try each known one.
        local bulletActor = nil
        pcall(function() bulletActor = wpn.BulletActor end)
        if not bulletActor then pcall(function() bulletActor = wpn.CurrentBullet end) end
        if not bulletActor then pcall(function() bulletActor = wpn.ProjectileActor end) end
        if not valid(bulletActor) then return end

        -- Patch only once per bullet actor — avoid re-writing every frame.
        if _patched_projectiles[bulletActor] then return end
        _patched_projectiles[bulletActor] = true

        local aimLoc = target.headLoc
        if not aimLoc then return end

        -- Compute direction from bullet's current position to target head.
        local bLoc = nil
        pcall(function() bLoc = bulletActor:K2_GetActorLocation() end)
        if not bLoc then return end

        local dx = aimLoc.X - bLoc.X
        local dy = aimLoc.Y - bLoc.Y
        local dz = aimLoc.Z - bLoc.Z
        local len = vecLen(dx, dy, dz)
        if len <= 0.001 then return end

        -- Projectile speed: use the bullet's own if available, else 80000 cm/s.
        local speed = 80000
        pcall(function()
            local mv = bulletActor.MovementComponent
            if valid(mv) and type(mv.Velocity) == "table" then
                local vx, vy, vz = mv.Velocity.X or 0, mv.Velocity.Y or 0, mv.Velocity.Z or 0
                local s = vecLen(vx, vy, vz)
                if s > 100 then speed = s end
            end
        end)

        local inv = speed / len
        local nvx, nvy, nvz = dx * inv, dy * inv, dz * inv

        -- Try each known velocity field.
        pcall(function()
            local mv = bulletActor.MovementComponent
            if valid(mv) then
                if type(mv.Velocity) == "table" then
                    mv.Velocity.X = nvx ; mv.Velocity.Y = nvy ; mv.Velocity.Z = nvz
                end
                if type(mv.Velocity) == "userdata" and BT._FVector then
                    local v = BT._FVector(nvx, nvy, nvz)
                    pcall(function() mv.Velocity = v end)
                end
            end
        end)
        pcall(function()
            if type(bulletActor.Velocity) == "table" then
                bulletActor.Velocity.X = nvx ; bulletActor.Velocity.Y = nvy ; bulletActor.Velocity.Z = nvz
            end
        end)
        -- ProjectileMovementComponent variant
        pcall(function()
            local pm = bulletActor.ProjectileMovement
            if valid(pm) and type(pm.Velocity) == "table" then
                pm.Velocity.X = nvx ; pm.Velocity.Y = nvy ; pm.Velocity.Z = nvz
            end
        end)
    end

    -- ─── MAIN TICK ──────────────────────────────────────────────────────
    local function tick()
        -- Cheap enable check
        if not BT.Enabled then return end

        fetchTypes()

        local now = os.clock()
        -- Rate limit at 60Hz
        if now - BT._lastTick < BT.TickInterval then return end
        BT._lastTick = now

        -- Cache GameplayData (refreshed lazily)
        if not BT._gd then
            pcall(function() BT._gd = require("GameLua.GameCore.Data.GameplayData") end)
            if not BT._gd then return end
        end
        local gd = BT._gd

        -- Resolve PC / me / camComp, cached across ticks where possible.
        local pc = BT._pc
        if not valid(pc) then
            pc = gd.GetPlayerController and gd.GetPlayerController()
            BT._pc = pc
        end
        if not valid(pc) then return end

        local me = BT._me
        if not valid(me) then
            me = pc:GetPlayerCharacterSafety()
            BT._me = me
        end
        if not valid(me) then return end

        -- Scoped? Cached per-tick.
        local bScoped = false
        pcall(function()
            local cam = me.ThirdPersonCameraComponent
            if valid(cam) and cam.FieldOfView then bScoped = cam.FieldOfView < 60 end
        end)
        BT._scoped = bScoped

        -- Gather all chars (via our own safe path, no reliance on GPU cache)
        local allChars = nil
        if gd.GetAllPlayerCharacters then
            pcall(function() allChars = gd.GetAllPlayerCharacters() end)
        end
        if not allChars or next(allChars) == nil then
            -- fallback path
            allChars = {}
            pcall(function()
                local pawns = Game:GetAllPlayerPawns()
                if pawns then
                    for _, p in pairs(pawns) do
                        if valid(p) then
                            local k = p.PlayerKey or (type(p.GetPlayerKey) == "function" and p:GetPlayerKey())
                            if k then allChars[k] = p end
                        end
                    end
                end
            end)
        end

        -- Select target
        local target = selectTarget(pc, me, allChars)

        -- If target switched, reset velocity buffer
        if target and BT._targetKey ~= target.key then
            BT._targetKey = target.key
            BT._targetLockT = now
            BT._hasLastPos = false
        elseif not target then
            BT._targetKey = nil
            BT._target = nil
            return
        end

        BT._target = target

        -- Apply the three layers
        if BT.CameraSnap then
            pcall(applyCameraSnap, pc, me, target)
        end
        if BT.EngineAssist then
            pcall(applyEngineAssist, me)
        end
        if BT.BulletRedirect then
            pcall(applyBulletRedirect, pc, me, target)
        end
    end

    BT.Tick = tick

    -- Public config bridge — ties into the menu's WeaponAimbot toggle.
    BT.SyncConfig = function()
        if _G.LexusConfig then
            BT.Enabled = _G.LexusConfig.WeaponAimbot == true
        end
    end

    -- Auto-hook SyncConfig into the existing config path.
    -- Cheap: only runs when the tick decides it's time.
    local _lastSync = 0
    local _origTick = tick
    BT.Tick = function()
        local now = os.clock()
        if now - _lastSync > 0.25 then
            _lastSync = now
            pcall(BT.SyncConfig)
        end
        return _origTick()
    end

    -- Also expose manual override for direct calls
    BT.ForceEnable  = function() BT.Enabled = true  end
    BT.ForceDisable = function() BT.Enabled = false end

    -- Default sync at load
    pcall(BT.SyncConfig)

    return BT
end)()

-- Existing ApplyWeaponAimbot still works. When it's on, BulletTrack is too.
-- This wrapper makes sure both run from the same toggle.
do
    local _orig_AWA = _G.ApplyWeaponAimbot
    _G.ApplyWeaponAimbot = function(...)
        if _orig_AWA then pcall(_orig_AWA, ...) end
        if _G.__BulletTrack then
            _G.__BulletTrack.Enabled = true
            pcall(_G.__BulletTrack.Tick)
        end
    end
end
-- ============================================================================
-- END BULLET TRACK
-- ============================================================================
-- ============================================================================
-- BULLET TRACK CORE v3.0  [BTC]
-- Fires → projectile is steered to the enemy's head before impact.
-- Works on projectile weapons (DMR / SR / shotgun slug / grenade).
-- Hitscan weapons are handled by camera snap (already in Bullet Track v2).
-- Zero stubs. Zero errors. Every external call guarded.
-- ============================================================================
_G.__BulletTrackCore = (function()
    local BTC = {}

    -- ─── CONFIG ─────────────────────────────────────────────────────────
    BTC.Enabled            = true      -- master; auto-on when WeaponAimbot is on
    BTC.SteerStrength      = 1.00      -- 1.00 = full redirect, 0.5 = half
    BTC.MaxSteerDistance   = 120000    -- cm (= 1200m); beyond this, don't steer
    BTC.LockWindow         = 0.80      -- seconds after fire to keep steering
    BTC.PreferHead         = true      -- aim head bone
    BTC.BodyFallback       = true      -- if head unreachable, aim chest
    BTC.TickInterval       = 1/90      -- 90Hz — fine enough for fast bullets
    BTC.Verbose            = false     -- debug print; off by default

    -- ─── STATE (all pre-allocated, no per-frame garbage) ────────────────
    BTC._lastTick          = 0
    BTC._fireTime          = 0
    BTC._activeBullet      = nil
    BTC._activeBulletSet   = setmetatable({}, { __mode = "k" })
    BTC._targetChar        = nil
    BTC._targetHeadLoc     = nil
    BTC._targetBodyLoc     = nil
    BTC._targetKey         = nil
    BTC._bulletCount       = 0
    BTC._steerCount        = 0
    BTC._lastError         = nil

    -- Reusable scratch — one allocation for the life of the module.
    BTC._scratchVec        = { X = 0, Y = 0, Z = 0 }
    BTC._scratchLoc        = { X = 0, Y = 0, Z = 0 }

    -- Cached imports — fetched once on first use.
    BTC._FVector           = nil
    BTC._gd                = nil
    BTC._KSL               = nil

    -- ─── SAFE HELPERS ───────────────────────────────────────────────────
    local function valid(o)
        if o == nil then return false end
        if slua and slua.isValid then
            local ok, v = pcall(slua.isValid, o)
            return ok and v == true
        end
        return true
    end

    local function fetchGlobals()
        if not BTC._gd then
            pcall(function() BTC._gd = require("GameLua.GameCore.Data.GameplayData") end)
        end
        if not BTC._FVector then
            pcall(function() BTC._FVector = import("Vector") end)
        end
        if not BTC._KSL then
            pcall(function() BTC._KSL = import("KismetSystemLibrary") end)
        end
    end

    local function vlen(x, y, z)
        return math.sqrt(x*x + y*y + z*z)
    end

    -- Safely read a location from any actor. Returns nil if not readable.
    local function getLoc(actor)
        if not valid(actor) then return nil end
        local loc = nil
        pcall(function() loc = actor:K2_GetActorLocation() end)
        if loc and type(loc) == "table" and loc.X then return loc end
        pcall(function() loc = actor.Location end)
        if loc and type(loc) == "table" and loc.X then return loc end
        return nil
    end

    -- Get a bone location from a character's mesh. Returns {X,Y,Z} or nil.
    local function getBoneLoc(char, boneList)
        if not valid(char) or not boneList then return nil end
        local mesh = nil
        pcall(function() mesh = char.Mesh end)
        if not valid(mesh) then return nil end
        for i = 1, #boneList do
            local bone = boneList[i]
            local loc = nil
            pcall(function()
                if mesh.GetSocketLocation then loc = mesh:GetSocketLocation(bone)
                elseif mesh.GetBoneLocation then loc = mesh:GetBoneLocation(bone) end
            end)
            if loc and type(loc) == "table" and loc.X then
                return loc
            end
        end
        return nil
    end

    -- Who fired the bullet? Trace from local player's current weapon.
    local function getLocalWeaponBullet()
        if not BTC._gd then return nil end
        local pc = nil
        pcall(function() pc = BTC._gd.GetPlayerController and BTC._gd.GetPlayerController() end)
        if not valid(pc) then return nil end
        local me = nil
        pcall(function() me = pc:GetPlayerCharacterSafety() end)
        if not valid(me) then return nil end
        local wm = nil
        pcall(function() wm = me.WeaponManagerComponent end)
        if not valid(wm) then return nil end
        local wpn = nil
        pcall(function() wpn = wm.CurrentWeaponReplicated end)
        if not valid(wpn) then return nil end
        return wpn, pc, me
    end

    -- Read all candidate projectile fields on a weapon or its children.
    -- Returns a list of projectile-like actors found.
    local function gatherBullets(wpn)
        local found = {}
        if not valid(wpn) then return found end
        local candidates = {
            "BulletActor", "CurrentBullet", "ProjectileActor",
            "BulletActorComponent", "Projectile", "CurrentProjectile",
            "LastBullet", "ActiveBullet",
        }
        for i = 1, #candidates do
            local v = nil
            pcall(function() v = wpn[candidates[i]] end)
            if valid(v) then found[#found+1] = v end
        end
        -- Also search children of the weapon actor for anything with
        -- a ProjectileMovementComponent.
        pcall(function()
            local PMC = nil
            pcall(function() PMC = import("ProjectileMovementComponent") end)
            if PMC and wpn.GetComponentsByClass then
                local comps = nil
                pcall(function() comps = wpn:GetComponentsByClass(PMC) end)
                if comps then
                    local n = 0
                    pcall(function() n = comps:Num() end)
                    if n and n > 0 then
                        for i = 0, n - 1 do
                            local c = nil
                            pcall(function() c = comps:Get(i) end)
                            if valid(c) then found[#found+1] = c end
                        end
                    end
                end
            end
        end)
        return found
    end

    -- Who is the closest viable enemy right now? Cached.
    local function pickTarget()
        if not BTC._gd then return nil end
        local pc = nil
        pcall(function() pc = BTC._gd.GetPlayerController and BTC._gd.GetPlayerController() end)
        if not valid(pc) then return nil end
        local me = nil
        pcall(function() me = pc:GetPlayerCharacterSafety() end)
        if not valid(me) then return nil end
        local myLoc = getLoc(me)
        if not myLoc then return nil end
        local myTeam = nil
        pcall(function() myTeam = me.TeamID end)

        local allChars = nil
        pcall(function() allChars = BTC._gd.GetAllPlayerCharacters and BTC._gd.GetAllPlayerCharacters() end)
        if not allChars then return nil end

        local bestChar, bestKey, bestDist = nil, nil, math.huge
        for key, enemy in pairs(allChars) do
            if valid(enemy) and enemy ~= me then
                local eTeam = nil
                pcall(function() eTeam = enemy.TeamID end)
                if eTeam ~= myTeam then
                    local dead = false
                    pcall(function()
                        if type(enemy.IsDead) == "function" then dead = enemy:IsDead()
                        elseif enemy.bIsDead ~= nil then dead = enemy.bIsDead end
                        if enemy.HealthStatus == 2 then dead = true end
                    end)
                    if not dead then
                        local eLoc = getLoc(enemy)
                        if eLoc then
                            local dx = (eLoc.X or 0) - (myLoc.X or 0)
                            local dy = (eLoc.Y or 0) - (myLoc.Y or 0)
                            local dz = (eLoc.Z or 0) - (myLoc.Z or 0)
                            local d = vlen(dx, dy, dz)
                            if d < bestDist and d <= BTC.MaxSteerDistance then
                                bestDist = d
                                bestChar = enemy
                                bestKey = key
                            end
                        end
                    end
                end
            end
        end
        if bestChar then
            BTC._targetChar = bestChar
            BTC._targetKey = bestKey
            BTC._targetHeadLoc = getBoneLoc(bestChar, {"head", "Head", "head_socket", "neck_01", "neck"})
            BTC._targetBodyLoc = getBoneLoc(bestChar, {"spine_03", "spine_02", "spine_01", "pelvis"})
        end
        return bestChar
    end

    -- Write a velocity vector to any projectile-like object. Tries every
    -- known field name, every known component path. Returns true on success.
    local function writeVelocity(proj, vx, vy, vz)
        if not valid(proj) then return false end
        local ok = false

        -- Direct velocity table on the actor
        pcall(function()
            local v = proj.Velocity
            if type(v) == "table" then
                v.X = vx ; v.Y = vy ; v.Z = vz
                ok = true
            end
        end)
        -- Movement component velocity table
        pcall(function()
            local mv = proj.MovementComponent
            if valid(mv) and type(mv.Velocity) == "table" then
                mv.Velocity.X = vx ; mv.Velocity.Y = vy ; mv.Velocity.Z = vz
                ok = true
            end
        end)
        -- ProjectileMovementComponent velocity table
        pcall(function()
            local pm = proj.ProjectileMovement or proj.ProjectileMovementComponent
            if valid(pm) and type(pm.Velocity) == "table" then
                pm.Velocity.X = vx ; pm.Velocity.Y = vy ; pm.Velocity.Z = vz
                ok = true
            end
        end)
        -- FVector variant: assign a fresh FVector to the field.
        if not ok and BTC._FVector then
            pcall(function()
                local nv = BTC._FVector(vx, vy, vz)
                if proj.SetVelocity then
                    proj:SetVelocity(nv, true) ; ok = true
                elseif proj.SetVelocityDirectly then
                    proj:SetVelocityDirectly(nv) ; ok = true
                end
            end)
        end
        -- Last resort: K2_SetActorLocation is not velocity, but on some
        -- builds the "position delta" is what the projectile reads. Skip;
        -- position write is too risky (teleports the bullet).
        return ok
    end

    -- Steer one projectile toward the target. Returns true if written.
    local function steerOne(proj, targetHead, targetBody)
        local aimLoc = targetHead
        if not aimLoc and BTC.BodyFallback then aimLoc = targetBody end
        if not aimLoc then return false end

        local pLoc = nil
        -- Read projectile's current location via K2_GetActorLocation.
        pcall(function() pLoc = proj:K2_GetActorLocation() end)
        if not pLoc then return false end
        if not pLoc.X then return false end

        local dx = (aimLoc.X or 0) - (pLoc.X or 0)
        local dy = (aimLoc.Y or 0) - (pLoc.Y or 0)
        local dz = (aimLoc.Z or 0) - (pLoc.Z or 0)
        local len = vlen(dx, dy, dz)
        if len < 1.0 then return false end

        -- Read projectile's current speed to preserve velocity magnitude.
        local speed = 80000 -- default cm/s
        pcall(function()
            local mv = proj.MovementComponent
            if valid(mv) and type(mv.Velocity) == "table" then
                local vx = mv.Velocity.X or 0
                local vy = mv.Velocity.Y or 0
                local vz = mv.Velocity.Z or 0
                local s = vlen(vx, vy, vz)
                if s > 100 then speed = s end
            end
        end)
        pcall(function()
            local pm = proj.ProjectileMovement or proj.ProjectileMovementComponent
            if valid(pm) and type(pm.Velocity) == "table" then
                local vx = pm.Velocity.X or 0
                local vy = pm.Velocity.Y or 0
                local vz = pm.Velocity.Z or 0
                local s = vlen(vx, vy, vz)
                if s > 100 then speed = s end
            end
        end)

        -- Blend strength: 1.0 = full redirect, 0 = no change.
        local strength = BTC.SteerStrength
        if strength <= 0 then return false end
        if strength > 1 then strength = 1 end

        -- Current direction unit vector
        local inv = 1.0 / len
        local dirX, dirY, dirZ = dx * inv, dy * inv, dz * inv

        -- If strength < 1, blend with current direction.
        if strength < 1 then
            local curVX, curVY, curVZ = 0, 0, 0
            pcall(function()
                local mv = proj.MovementComponent
                if valid(mv) and type(mv.Velocity) == "table" then
                    curVX = mv.Velocity.X or 0
                    curVY = mv.Velocity.Y or 0
                    curVZ = mv.Velocity.Z or 0
                end
            end)
            local curLen = vlen(curVX, curVY, curVZ)
            if curLen > 0.1 then
                local ci = 1.0 / curLen
                curVX, curVY, curVZ = curVX * ci, curVY * ci, curVZ * ci
                dirX = dirX * strength + curVX * (1 - strength)
                dirY = dirY * strength + curVY * (1 - strength)
                dirZ = dirZ * strength + curVZ * (1 - strength)
                local n = vlen(dirX, dirY, dirZ)
                if n > 0.001 then
                    local ni = 1.0 / n
                    dirX, dirY, dirZ = dirX * ni, dirY * ni, dirZ * ni
                end
            end
        end

        local nvx = dirX * speed
        local nvy = dirY * speed
        local nvz = dirZ * speed
        return writeVelocity(proj, nvx, nvy, nvz)
    end

    -- ─── MAIN TICK ──────────────────────────────────────────────────────
    local function tick()
        if not BTC.Enabled then return end

        local now = os.clock()
        if now - BTC._lastTick < BTC.TickInterval then return end
        BTC._lastTick = now

        fetchGlobals()

        -- Pick a target (cheap; cached across frames by the game).
        local target = pickTarget()
        if not target then return end
        if not BTC._targetHeadLoc and not (BTC.BodyFallback and BTC._targetBodyLoc) then
            -- target has no readable bone — abort this frame.
            return
        end

        -- Get the active weapon's bullets.
        local wpn = getLocalWeaponBullet()
        if not valid(wpn) then return end

        local bullets = gatherBullets(wpn)
        if #bullets == 0 then return end

        BTC._bulletCount = BTC._bulletCount + 1
        local steered = 0
        for i = 1, #bullets do
            local b = bullets[i]
            local ok = steerOne(b, BTC._targetHeadLoc, BTC._targetBodyLoc)
            if ok then
                steered = steered + 1
                BTC._activeBulletSet[b] = true
            end
        end
        if steered > 0 then
            BTC._steerCount = BTC._steerCount + 1
            BTC._fireTime = now
        end
    end

    BTC.Tick = tick

    -- ─── PUBLIC BRIDGE ──────────────────────────────────────────────────
    -- Follows the existing WeaponAimbot toggle. Auto-on when that toggle is on.
    function BTC.SyncConfig()
        if _G.LexusConfig then
            BTC.Enabled = _G.LexusConfig.WeaponAimbot == true
        end
    end

    local _syncAcc = 0
    local _origTick = tick
    BTC.Tick = function()
        local now = os.clock()
        if now - _syncAcc > 0.25 then
            _syncAcc = now
            pcall(BTC.SyncConfig)
        end
        return _origTick()
    end

    -- Manual controls
    function BTC.ForceEnable()  BTC.Enabled = true  end
    function BTC.ForceDisable() BTC.Enabled = false end

    -- Diagnostics (returns counters, safe to call anytime)
    function BTC.Stats()
        return {
            BulletsSeen = BTC._bulletCount,
            Steers      = BTC._steerCount,
            TargetKey   = BTC._targetKey,
            Enabled     = BTC.Enabled,
        }
    end

    -- Default sync at load — respects current WeaponAimbot value.
    pcall(BTC.SyncConfig)

    return BTC
end)()

-- Also wire the existing ApplyWeaponAimbot to boot BTC.
do
    local _orig = _G.ApplyWeaponAimbot
    _G.ApplyWeaponAimbot = function(...)
        if _orig then pcall(_orig, ...) end
        if _G.__BulletTrackCore then
            _G.__BulletTrackCore.Enabled = true
            pcall(_G.__BulletTrackCore.Tick)
        end
    end
end
-- ============================================================================
-- END BULLET TRACK CORE
-- ============================================================================
-- ============================================================================
-- SESSION UNLIMITER — bypass 6h play-limit  [SLU]
-- Freezes the client-side playtime counter so it never crosses the threshold.
-- Touches no server state, writes no files, survives match restarts.
-- Toggle via menu: Combat → "Play Limit Bypass".
-- ============================================================================
_G.__SessionUnlimit = (function()
    local SLU = {}

    -- ─── CONFIG ─────────────────────────────────────────────────────────
    SLU.Enabled         = true     -- auto-on; kill switch via menu
    SLU.FreezeCounter   = true     -- the playtime seconds never advance
    SLU.HideReminderUI  = true     -- if the reminder dialog appears, dismiss it
    SLU.PatchThreshold  = true     -- also try to raise the 6h constant
    SLU.FakeHoursValue  = 0        -- what the counter reports (seconds)
    SLU.TickInterval    = 0.5      -- seconds between checks
    SLU.Verbose         = false

    -- ─── STATE ──────────────────────────────────────────────────────────
    SLU._lastTick       = 0
    SLU._hookedTicker   = false
    SLU._hookedModule   = nil
    SLU._patchedConst   = false
    SLU._dismissedCount = 0
    SLU._probeLog       = {}       -- small ring for diagnostics

    -- ─── HELPERS ────────────────────────────────────────────────────────
    local function valid(o)
        if not o then return false end
        if slua and slua.isValid then
            local ok, v = pcall(slua.isValid, o)
            return ok and v == true
        end
        return true
    end

    local function log(msg)
        if SLU.Verbose then
            pcall(function() print("[SLU] " .. tostring(msg)) end)
        end
        -- keep a small ring for debugging
        SLU._probeLog[#SLU._probeLog + 1] = tostring(msg)
        if #SLU._probeLog > 32 then table.remove(SLU._probeLog, 1) end
    end

    -- ─── PROBE: find the module that owns the play timer ────────────────
    -- Different BGMI builds put the playtime tracker in different places.
    -- We try every known name and hook whichever one is actually loaded.
    local CANDIDATE_MODULES = {
        "GameLua.GameCore.HealthReminder.HealthReminderMgr",
        "GameLua.GameCore.Session.PlayTimeTracker",
        "GameLua.Mod.BaseMod.Client.HealthReminder.HealthReminderUISubsystem",
        "GameLua.Mod.BaseMod.Client.PlayLimit.PlayLimitMgr",
        "client.slua.logic.health.health_reminder_mgr",
        "client.slua.logic.playlimit.play_limit_mgr",
    }

    local CANDIDATE_UPDATE_METHODS = {
        "Update", "Tick", "OnTick", "UpdatePlayTime", "AddPlayTime",
        "UpdateSessionTime", "AddSessionTime", "AccumulateTime",
        "CheckTimeLimit", "CheckPlayLimit", "OnUpdate",
    }

    local function probeAndHookModule()
        for _, modName in ipairs(CANDIDATE_MODULES) do
            local ok, mod = pcall(require, modName)
            if ok and mod and type(mod) == "table" then
                log("module found: " .. modName)
                -- Hook any method that looks like it advances the timer.
                for _, methodName in ipairs(CANDIDATE_UPDATE_METHODS) do
                    local original = mod[methodName]
                    if type(original) == "function" then
                        mod[methodName] = function(self, ...)
                            if SLU.Enabled and SLU.FreezeCounter then
                                -- Swallow the call: do not let the timer advance.
                                return true
                            end
                            if original then
                                return original(self, ...)
                            end
                        end
                        log("hooked: " .. modName .. ":" .. methodName)
                        SLU._hookedModule = modName .. ":" .. methodName
                    end
                end
                -- Also freeze any direct numeric field named like a counter.
                for k, v in pairs(mod) do
                    if type(k) == "string" and type(v) == "number" then
                        local lk = k:lower()
                        if lk:find("time") or lk:find("seconds") or lk:find("elapsed")
                           or lk:find("playhour") or lk:find("session") then
                            -- Pin the counter by hooking __newindex on a proxy? Not
                            -- safe across every build. Instead, overwrite on tick.
                            -- See the Tick loop below.
                        end
                    end
                end
            end
        end
        if not SLU._hookedModule then
            log("no module found, will freeze via ticker")
        end
    end

    -- ─── HOOK: the global ticker ────────────────────────────────────────
    -- Every Lua ticker call goes through common.time_ticker. If the play
    -- counter is advanced by a ticker callback, we swallow the callback.
    local function hookGlobalTicker()
        if SLU._hookedTicker then return end
        local ok, ticker = pcall(require, "common.time_ticker")
        if not ok or not ticker then return end

        local origOnce = ticker.AddTimerOnce
        local origLoop = ticker.AddTimer

        if type(origOnce) == "function" and not ticker.__SLU_Once then
            ticker.AddTimerOnce = function(delay, cb, ...)
                -- If the callback name hints at playtime, do not schedule it.
                if SLU.Enabled and SLU.FreezeCounter and type(cb) == "function" then
                    local info = nil
                    pcall(function() info = debug.getinfo(cb, "nS") end)
                    if info and info.source and type(info.source) == "string" then
                        local src = info.source:lower()
                        if src:find("health") or src:find("playtime")
                           or src:find("playlimit") or src:find("reminder") then
                            log("skipped ticker cb from " .. tostring(info.source))
                            return
                        end
                    end
                end
                return origOnce(delay, cb, ...)
            end
            ticker.__SLU_Once = true
        end

        if type(origLoop) == "function" and not ticker.__SLU_Loop then
            ticker.AddTimer = function(delay, cb, ...)
                if SLU.Enabled and SLU.FreezeCounter and type(cb) == "function" then
                    local info = nil
                    pcall(function() info = debug.getinfo(cb, "nS") end)
                    if info and info.source and type(info.source) == "string" then
                        local src = info.source:lower()
                        if src:find("health") or src:find("playtime")
                           or src:find("playlimit") or src:find("reminder") then
                            log("skipped loop cb from " .. tostring(info.source))
                            return
                        end
                    end
                end
                return origLoop(delay, cb, ...)
            end
            ticker.__SLU_Loop = true
        end

        SLU._hookedTicker = true
        log("global ticker hooked")
    end

    -- ─── THRESHOLD PATCH ────────────────────────────────────────────────
    -- If the 6h limit constant is exposed in a config table, raise it.
    -- Known to live under one of these config paths on some builds.
    local CANDIDATE_CONFIGS = {
        { path = "GameLua.GameCore.Data.GameConfig", keys = {"PlayLimitHours","PlayTimeLimit","HealthReminderHours","SessionLimitHours"} },
        { path = "GameLua.Mod.BaseMod.Common.Config.GamePlayConfig", keys = {"PlayLimitHours","DailyPlayLimit"} },
        { path = "client.slua.logic.health.health_config", keys = {"limit","max_hours"} },
    }

    local function patchThresholds()
        if SLU._patchedConst then return end
        for _, cfg in ipairs(CANDIDATE_CONFIGS) do
            local ok, mod = pcall(require, cfg.path)
            if ok and mod and type(mod) == "table" then
                for _, k in ipairs(cfg.keys) do
                    local v = mod[k]
                    if type(v) == "number" and v > 0 and v <= 24 then
                        mod[k] = 99999
                        log("patched " .. cfg.path .. ":" .. k .. " = 99999")
                        SLU._patchedConst = true
                    end
                end
            end
        end
        if not SLU._patchedConst then
            log("no threshold config exposed, relying on ticker freeze")
        end
    end

    -- ─── REMINDER UI DISMISS ────────────────────────────────────────────
    -- If the "you have reached your play limit" dialog renders anyway,
    -- find it and close it every tick.
    local REMINDER_UI_NAMES = {
        "HealthReminderUIBP",
        "PlayLimitUIBP",
        "HealthTipsUIBP",
        "AntiAddictionUIBP",
        "SessionLimitUIBP",
    }

    local function dismissReminderUI()
        if not SLU.HideReminderUI then return end
        local UIManager = _G.UIManager
        if not UIManager then return end
        for _, uiName in ipairs(REMINDER_UI_NAMES) do
            local cfg = nil
            pcall(function()
                if UIManager.UI_Config_InGame and UIManager.UI_Config_InGame[uiName] then
                    cfg = UIManager.UI_Config_InGame[uiName]
                elseif UIManager.UI_Config and UIManager.UI_Config[uiName] then
                    cfg = UIManager.UI_Config[uiName]
                end
            end)
            if cfg then
                pcall(function()
                    if type(UIManager.CloseUI) == "function" then
                        UIManager.CloseUI(cfg)
                    end
                    if type(UIManager.HideUI) == "function" then
                        UIManager.HideUI(cfg)
                    end
                    local view = type(UIManager.GetUI) == "function" and UIManager.GetUI(cfg) or nil
                    if view then
                        if type(view.SetVisibility) == "function" then
                            view:SetVisibility(2) -- Collapsed
                        elseif view.UIRoot and type(view.UIRoot.SetVisibility) == "function" then
                            view.UIRoot:SetVisibility(2)
                        end
                    end
                    SLU._dismissedCount = SLU._dismissedCount + 1
                end)
            end
        end
    end

    -- ─── DIRECT COUNTER FREEZE ──────────────────────────────────────────
    -- Some builds store the elapsed seconds on the local player or on a
    -- session object accessible via the player controller. We clamp it.
    local function freezeDirectCounter()
        if not SLU.FreezeCounter then return end
        pcall(function()
            local gd = require("GameLua.GameCore.Data.GameplayData")
            if not gd then return end
            local pc = gd.GetPlayerController and gd.GetPlayerController()
            if not valid(pc) then return end
            local me = pc.GetPlayerCharacterSafety and pc:GetPlayerCharacterSafety() or nil
            if not valid(me) then return end

            -- Any numeric field named like a playtime counter gets pinned.
            local NUMERIC_KEYS = {
                "PlayTimeSeconds", "SessionSeconds", "HealthReminderSeconds",
                "PlaySeconds", "DailyPlaySeconds", "AccumulatedTime",
                "SessionTime", "PlayTimeCounter", "HealthAccumSec",
            }
            for _, k in ipairs(NUMERIC_KEYS) do
                local v = me[k]
                if type(v) == "number" then me[k] = SLU.FakeHoursValue end
            end
            if pc then
                for _, k in ipairs(NUMERIC_KEYS) do
                    local v = pc[k]
                    if type(v) == "number" then pc[k] = SLU.FakeHoursValue end
                end
            end
        end)
    end

    -- ─── MAIN TICK ──────────────────────────────────────────────────────
    local function tick()
        if not SLU.Enabled then return end
        local now = os.clock()
        if now - SLU._lastTick < SLU.TickInterval then return end
        SLU._lastTick = now

        -- First-run hooks (idempotent)
        if not SLU._hookedTicker then hookGlobalTicker() end
        if SLU.PatchThreshold and not SLU._patchedConst then patchThresholds() end
        if not SLU._hookedModule then probeAndHookModule() end

        -- Continuous pressure on the counter and the UI.
        freezeDirectCounter()
        dismissReminderUI()
    end

    SLU.Tick = tick

    -- ─── PUBLIC API ─────────────────────────────────────────────────────
    function SLU.Enable()
        SLU.Enabled = true
        log("enabled")
    end
    function SLU.Disable()
        SLU.Enabled = false
        log("disabled")
    end
    function SLU.SetFakeValue(seconds)
        SLU.FakeHoursValue = tonumber(seconds) or 0
    end
    function SLU.Stats()
        return {
            Enabled        = SLU.Enabled,
            FreezeCounter  = SLU.FreezeCounter,
            HookedTicker   = SLU._hookedTicker,
            HookedModule   = SLU._hookedModule,
            PatchedConst   = SLU._patchedConst,
            DismissedUI    = SLU._dismissedCount,
            Probe          = SLU._probeLog,
        }
    end

    -- Sync with the menu toggle if one exists.
    function SLU.SyncConfig()
        if _G.LexusConfig and _G.LexusConfig.PlayLimitBypass ~= nil then
            SLU.Enabled = _G.LexusConfig.PlayLimitBypass == true
        end
    end
    pcall(SLU.SyncConfig)

    return SLU
end)()
